package com.ruoyi.business.ai.capability.project;
import java.util.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.stereotype.Component;import com.ruoyi.business.ai.capability.*;import com.ruoyi.business.domain.BusinessProjectRoutine;import com.ruoyi.business.service.IBusinessProjectService;import static com.ruoyi.business.ai.capability.AiCapabilityInputs.*;
@Component public class SaveProjectRoutineCapability implements AiConfirmableCapability{private final IBusinessProjectService service;@Autowired public SaveProjectRoutineCapability(IBusinessProjectService s){service=s;}public String code(){return "project.routine.save";}public String description(){return "新增或修改持续重复工作及周期目标。修改时先读取项目详情取得routineId和version；确认后执行。";}public String requiredPermission(){return "business:project:task";}public Map<String,Object> inputSchema(){Map<String,Object>s=AiSchemas.object();AiSchemas.property(s,"projectId","number","项目ID");AiSchemas.property(s,"routineId","number","修改时的持续工作ID");AiSchemas.property(s,"version","number","修改时当前版本");AiSchemas.property(s,"routineName","string","持续工作名称");AiSchemas.property(s,"frequency","string","DAILY/WEEKLY/MONTHLY");AiSchemas.property(s,"targetValue","number","每周期目标值，大于0");AiSchemas.property(s,"unit","string","成果单位");AiSchemas.property(s,"assigneeUserId","number","执行人用户ID，必须是项目成员");AiSchemas.property(s,"startDate","string","开始日期 YYYY-MM-DD");AiSchemas.property(s,"endDate","string","结束日期 YYYY-MM-DD");AiSchemas.property(s,"evidenceRequired","string","1要求成果凭证，0不要求");AiSchemas.property(s,"remark","string","安排说明");return AiSchemas.required(s,"projectId","routineName","targetValue","unit","assigneeUserId");}
 public String confirmationSummary(AiCapabilityInvocation i,Map<String,Object>in){return (number(in.get("routineId"))==null?"新增":"修改")+"持续工作“"+text(in.get("routineName"))+"”，目标 "+text(in.get("targetValue"))+" "+text(in.get("unit"))+"/"+(upper(in.get("frequency")).isEmpty()?"DAILY":upper(in.get("frequency")));}
 public Map<String,Object> executeConfirmed(AiCapabilityInvocation i,Map<String,Object>in){BusinessProjectRoutine x=new BusinessProjectRoutine();x.setProjectId(number(in.get("projectId")));x.setRoutineId(number(in.get("routineId")));x.setVersion(integer(in.get("version")));x.setRoutineName(text(in.get("routineName")));x.setFrequency(upper(in.get("frequency")));x.setTargetValue(decimal(in.get("targetValue")));x.setUnit(text(in.get("unit")));x.setAssigneeUserId(number(in.get("assigneeUserId")));x.setStartDate(date(in.get("startDate")));x.setEndDate(date(in.get("endDate")));x.setEvidenceRequired(text(in.get("evidenceRequired")));x.setRemark(text(in.get("remark")));BusinessProjectRoutine saved=service.saveRoutine(x,i.getActor().getUserId(),i.getActor().getUserName(),true);Map<String,Object>r=new LinkedHashMap<String,Object>();r.put("projectId",saved.getProjectId());r.put("routineId",saved.getRoutineId());r.put("routineName",saved.getRoutineName());r.put("assigneeName",saved.getAssigneeName());r.put("targetValue",saved.getTargetValue());r.put("unit",saved.getUnit());r.put("version",saved.getVersion());return r;}}
